//! The safety model: every opportunity, step and journal entry carries a [`SafetyClass`].

use serde::{Deserialize, Serialize};

/// How reversible an action is. Drives the card badge, the hero bar bucket,
/// whether confirmation is required and the colour of the acting button.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum SafetyClass {
    /// Undoable from History (Recycle Bin/Trash, quarantine, move, lossless rewrite with backup).
    Reversible,
    /// Removed content can be regenerated by a tool (node_modules, caches); removal goes via Trash.
    Rebuildable,
    /// A smaller copy is written beside the original; nothing is removed.
    LightCopy,
    /// Lossy transform the user must opt in to; originals follow the originals policy.
    LossyOptIn,
    /// Shown for review only; MyJanitor proposes no automatic action.
    ReviewOnly,
    /// Irreversible (permanent delete, shred, free-space wipe).
    Permanent,
}

/// The three segments of the hero savings bar.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum SavingsBucket {
    /// Reversible, Rebuildable, LightCopy.
    Reversible,
    /// LossyOptIn and Permanent: needs explicit confirmation.
    OptIn,
    /// ReviewOnly.
    ReviewOnly,
}

impl SafetyClass {
    /// Hero-bar bucket.
    pub fn bucket(self) -> SavingsBucket {
        match self {
            SafetyClass::Reversible | SafetyClass::Rebuildable | SafetyClass::LightCopy => SavingsBucket::Reversible,
            SafetyClass::LossyOptIn | SafetyClass::Permanent => SavingsBucket::OptIn,
            SafetyClass::ReviewOnly => SavingsBucket::ReviewOnly,
        }
    }

    /// True when applying needs the confirmation dialog (SAF-11).
    pub fn requires_confirmation(self) -> bool {
        matches!(self, SafetyClass::LossyOptIn | SafetyClass::Permanent)
    }

    /// True when the action can be undone from History.
    pub fn is_undoable(self) -> bool {
        !matches!(self, SafetyClass::Permanent | SafetyClass::LossyOptIn)
    }

    /// Badge label (rendered uppercase by the UI).
    pub fn label(self) -> &'static str {
        match self {
            SafetyClass::Reversible => "reversible",
            SafetyClass::Rebuildable => "rebuildable",
            SafetyClass::LightCopy => "light copy",
            SafetyClass::LossyOptIn => "lossy · opt-in",
            SafetyClass::ReviewOnly => "review only",
            SafetyClass::Permanent => "permanent",
        }
    }
}
